const configText = $input.item.json.stdout || '{}';
const config = JSON.parse(configText);

// Generate timestamp for output files
const now = new Date();
const timestamp = now.toISOString().replace(/[:.]/g, '-').slice(0, 19);

return [{
  json: {
    jobTitles: config.job_titles || ['Engineering Manager'],
    location: config.location || 'London, UK',
    timeRange: config.time_range || '48h',
    excludeKeywords: config.exclude_keywords || [],
    mustHaveKeywords: config.must_have || [],
    minScore: config.min_score || 6,
    maxJobs: config.max_jobs_per_title || 20,
    ollamaModel: config.ollama_model || 'Qwen2.5:latest',
    ollamaUrl: config.ollama_url || 'http://host.docker.internal:11434',
    // Metadata for output files
    runTimestamp: timestamp,
    outputFileMatches: `/data/n8n_linkedin/output/matches_${timestamp}.json`,
    outputFileRejected: `/data/n8n_linkedin/output/rejected_${timestamp}.json`,
    metadata: {
      source: 'LinkedIn (via Python scraper)',
      aiProvider: 'Ollama (local)',
      aiModel: config.ollama_model || 'Qwen2.5:latest',
      candidateName: 'Joao Lourenco',
      runDate: now.toISOString(),
      configVersion: '1.0'
    }
  }
}];

// Create output directory and pass through config
const config = $input.item.json;

// Note: mkdir will be done via shell in the scraper step
// This node just passes through the config
return [{ json: config }];

// Parse JSON and split into individual job items
const jobsText = $input.item.json.stdout || '[]';
let jobs = [];

try {
  jobs = JSON.parse(jobsText);
} catch(e) {
  console.log('Parse error:', e.message);
  return [];
}

if (!Array.isArray(jobs) || jobs.length === 0) {
  return [];
}

const config = $('Parse Config').item.json;
const searchTitle = $('Split Job Titles').item.json.jobTitles;

console.log('Found ' + jobs.length + ' jobs for: ' + searchTitle);

// Return each job as separate item with all data embedded
return jobs.map((job, idx) => ({
  json: {
    _idx: idx,
    title: job.title || '',
    company: job.company || '',
    location: job.location || '',
    job_link: job.job_link || '',
    posted_date: job.posted_date || '',
    description: job.description || '',
    searchTitle: searchTitle,
    config: config
  }
}));

