// Get Ollama response from HTTP request
const ollamaResponse = $input.item.json;

// Get job data from the Loop Jobs node
const jobData = $('Loop Jobs').item.json;

console.log('Processing: ' + jobData.title + ' at ' + jobData.company);

let ollamaContent = ollamaResponse.message?.content || '{}';

try {
  // Extract JSON from possible markdown blocks
  const jsonMatch = ollamaContent.match(/```json\s*([\s\S]*?)```/) || 
                    ollamaContent.match(/```\s*([\s\S]*?)```/) ||
                    ollamaContent.match(/\{[\s\S]*\}/);
  if (jsonMatch) ollamaContent = jsonMatch[1] || jsonMatch[0];

  const analysis = JSON.parse(ollamaContent.trim());
  console.log('Score: ' + analysis.score + ', Relevant: ' + analysis.relevant);

  return [{
    json: {
      title: jobData.title,
      company: jobData.company,
      location: jobData.location,
      job_link: jobData.job_link,
      posted_date: jobData.posted_date,
      description: jobData.description,
      searchTitle: jobData.searchTitle,
      config: jobData.config,
      analysis: {
        relevant: analysis.relevant ?? false,
        rejection_reason: analysis.rejection_reason || null,
        score: parseInt(analysis.score) || 0,
        company_size: analysis.company_size || 'Unknown',
        company_industry: analysis.company_industry || 'Unknown',
        company_about: analysis.company_about || '',
        role_summary: analysis.role_summary || '',
        match_reasons: Array.isArray(analysis.match_reasons) ? analysis.match_reasons : [],
        concerns: Array.isArray(analysis.concerns) ? analysis.concerns : [],
        seniority_level: analysis.seniority_level || 'Unknown'
      }
    }
  }];
} catch (e) {
  console.log('Parse error: ' + e.message);
  return [{
    json: {
      title: jobData.title,
      company: jobData.company,
      location: jobData.location,
      job_link: jobData.job_link,
      posted_date: jobData.posted_date,
      searchTitle: jobData.searchTitle,
      config: jobData.config,
      analysis: {
        relevant: false,
        rejection_reason: 'Parse error: ' + e.message,
        score: 0,
        company_size: 'Unknown',
        company_industry: 'Unknown',
        company_about: '',
        role_summary: '',
        match_reasons: [],
        concerns: ['AI parse failed'],
        seniority_level: 'Unknown'
      }
    }
  }];
}

