// Get cover letter from Ollama response
const coverLetter = $input.item.json.message?.content || 'Generation failed';

// Get job data from Filter node
const jobData = $('Filter: Relevant?').item.json;
const config = jobData.config;

// Build the complete job record with cover letter
const jobRecord = {
  // Job information
  job: {
    title: jobData.title,
    company: jobData.company,
    location: jobData.location,
    job_link: jobData.job_link,
    posted_date: jobData.posted_date,
    description: jobData.description
  },
  // AI analysis
  analysis: jobData.analysis,
  // Cover letter
  cover_letter: coverLetter.replace(/```/g, '').trim(),
  // Metadata
  metadata: {
    ...config.metadata,
    searchTitle: jobData.searchTitle,
    processedAt: new Date().toISOString(),
    status: 'matched'
  }
};

return [{
  json: {
    jobRecord: jobRecord,
    outputFile: config.outputFileMatches,
    config: config
  }
}];

// Save match record to JSON file using base64 to avoid shell escaping issues
const jobRecord = $input.item.json.jobRecord;
const outputFile = $input.item.json.outputFile;
const config = $input.item.json.config;

// Convert record to base64 to safely pass to shell
const recordJson = JSON.stringify(jobRecord);
const recordBase64 = Buffer.from(recordJson).toString('base64');

return [{
  json: {
    recordBase64: recordBase64,
    outputFile: outputFile,
    config: config
  }
}];

// Get job data from Filter node (false branch = rejected)
const jobData = $input.item.json;
const config = jobData.config;

// Build the rejected job record
const jobRecord = {
  // Job information
  job: {
    title: jobData.title,
    company: jobData.company,
    location: jobData.location,
    job_link: jobData.job_link,
    posted_date: jobData.posted_date
  },
  // AI analysis (why rejected)
  analysis: {
    relevant: jobData.analysis.relevant,
    rejection_reason: jobData.analysis.rejection_reason || `Score ${jobData.analysis.score} below minimum ${config.minScore}`,
    score: jobData.analysis.score,
    company_size: jobData.analysis.company_size,
    company_industry: jobData.analysis.company_industry,
    seniority_level: jobData.analysis.seniority_level
  },
  // Metadata
  metadata: {
    ...config.metadata,
    searchTitle: jobData.searchTitle,
    processedAt: new Date().toISOString(),
    status: 'rejected'
  }
};

return [{
  json: {
    jobRecord: jobRecord,
    outputFile: config.outputFileRejected,
    config: config
  }
}];

// Encode rejected record to base64 for safe shell passing
const jobRecord = $input.item.json.jobRecord;
const outputFile = $input.item.json.outputFile;
const config = $input.item.json.config;

const recordJson = JSON.stringify(jobRecord);
const recordBase64 = Buffer.from(recordJson).toString('base64');

return [{
  json: {
    recordBase64: recordBase64,
    outputFile: outputFile,
    config: config
  }
}];
